const MAX_BYTES=2000*1000*1000;const allowed=new Set(["wav","flac","m4a"]);const input=document.querySelector("#audio-file"),zone=document.querySelector("#drop-zone"),result=document.querySelector("#file-result"),error=document.querySelector("#upload-error"),nameEl=document.querySelector("#file-name"),metaEl=document.querySelector("#file-meta");function showFile(file){const ext=(file.name.split(".").pop()||"").toLowerCase();let message="";if(!allowed.has(ext))message="รองรับเฉพาะ WAV, FLAC และ ALAC (.m4a)";else if(file.size>MAX_BYTES)message="ไฟล์มีขนาดเกิน 2,000 MB กรุณาเลือกไฟล์ที่เล็กกว่า";error.hidden=!message;error.textContent=message;result.hidden=Boolean(message);if(message){input.value="";return}nameEl.textContent=file.name;metaEl.textContent=(file.size/1000000).toFixed(2)+" MB · "+ext.toUpperCase()}input.addEventListener("change",()=>input.files[0]&&showFile(input.files[0]));["dragenter","dragover"].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.add("is-dragging")}));["dragleave","drop"].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.remove("is-dragging")}));zone.addEventListener("drop",e=>{const file=e.dataTransfer.files[0];if(file)showFile(file)});